import torchimport torch.nn as nnfrom torch.utils.data import DataLoaderfrom torchvision import datasets, transformsimport matplotlib.pyplot as plttransform = transforms.ToTensor()train_dataset = datasets.MNIST(    root="./data",    train=True,    download=True,    transform=transform)loader = DataLoader(    train_dataset,    batch_size=128,    shuffle=True)class Encoder(nn.Module):    def __init__(self, latent_dim):        super().__init__()        self.network = nn.Sequential(            nn.Linear(784,128),            nn.ReLU(),            nn.Linear(128,64),            nn.ReLU()        )        self.mu = nn.Linear(            64,            latent_dim        )        self.logvar = nn.Linear(            64,            latent_dim        )    def forward(self,x):        h = self.network(x)        mu = self.mu(h)        logvar = self.logvar(h)        return mu, logvar            #fght yek noghte nemdie, ham mu midd ham klogvar            #in ytek tricki hast k tadris#random error ezaf emikone k z betone skahte bashe    def reparameterize(mu, logvar):    std = torch.exp(        0.5 * logvar    )    eps = torch.randn_like(std)    z = mu + eps * std    return z#latent dimention 32 --> 784class Decoder(nn.Module):    def __init__(self,latent_dim):        super().__init__()        self.network = nn.Sequential(            nn.Linear(latent_dim,64),            nn.ReLU(),            nn.Linear(64,128),            nn.ReLU(),            nn.Linear(128,784),            nn.Sigmoid()        )    def forward(self,z):        return self.network(z)                                        '''yek class misazim bename encoderdecoderrreparmaterizationhamashon miran zire class VAE'''    class VAE(nn.Module):    def __init__(self,latent_dim):        super().__init__()        self.encoder = Encoder(            latent_dim        )        self.decoder = Decoder(            latent_dim        )    def forward(self,x):                #vorodi ro migire --> encoder --> 784-->128-->64-->32                #32 -->dot aetwok lienar --> miu, log variance (distribution)                        mu,logvar = self.encoder(x)        #miu va log variance --> random yek noighte--> trick prepamaterization        #-->noghte        z = reparameterize(            mu,            logvar        )                        #noghte --> decoder 1 --> 784        reconstruction = self.decoder(z)        return reconstruction,mu,logvar                    latent_dim = 32model = VAE(    latent_dim)#modelamo sakhtamdef vae_loss(    reconstruction,    x,    mu,    logvar):            #yek loss baraye inke biad vorodi va khroji yeksan --> Autoencoder    recon_loss = nn.functional.binary_cross_entropy(        reconstruction,        x,        reduction="sum"    )            #kd --> yani bessanze cheghadr toiz ha ghavi kenare ham hamposhani        kl_loss = -0.5 * torch.sum(        1 + logvar        - mu.pow(2)        - logvar.exp()    )    return recon_loss + kl_lossoptimizer = torch.optim.Adam(    model.parameters(),    lr=0.001)#20 bar epochs=20for epoch in range(epochs):    total_loss=0    for images,_ in loader:                #image --> laoder                        #28 x 28 --> 784        images = images.view(            images.size(0),            -1        )                        #model --> encoder --> miu, var ---> decodeer --> recostrcion                        reconstruction,mu,logvar = model(images)        #loss = loss autoencoderfr (input - output) + KD (misanje latent )                loss = vae_loss(            reconstruction,            images,            mu,            logvar        )        optimizer.zero_grad()        loss.backward()        optimizer.step()        total_loss += loss.item()    print(        epoch,        total_loss/len(loader)    )            '''information hato inja benevis3 shahrivar 19:540 26360.4030267190831 20282.2824285381142 17785.237875216553 16583.50383337224 15845.5996343616735 15395.588948394196 15102.4541806869677 14873.0466584488288 14710.548923907259 14577.80934335021310 14480.69329899053811 14391.62799423640712 14318.7610607675913 14258.2348997201514 14201.76373642390715 14160.41746068763316 14112.34942613939217 14073.36612348414218 14037.31170250866119 13999.265096115405niaz dare lr --> bishtar konmepoch 200'''             #reconstruction exampleimages,_ = next(iter(loader))#image --> 28 x 28 #-->784->vorodi bedamx = images[0].view(    1,    784)model.eval()with torch.no_grad():    reconstruction,mu,logvar = model(x)    #model --> encoder --> decoder (VAE)--> reconstruction#latent ro jori misaze -->k moratab k badan btonim az ddcodresh estefade konim       plt.subplot(1,2,1)plt.imshow(    x.view(28,28),    cmap="gray")plt.title("Original")plt.subplot(1,2,2)plt.imshow(    reconstruction.view(28,28),    cmap="gray")plt.title("VAE Output")plt.show()#tanha farghesh ba autoencoder ine ke #auto encoder --> model.encoder() --> preprpcessin#z --> model.decoder() ---> ax generate kone#latent space monazame --> z bdm --> miu, ..#z --> hatman too yeki az distribution haye ax hame (dataset)#hamon nist noghte, hamposhani --> yek ax shabihe on misaze baram#yek axi besazam k daghigh hamon axoi ndrm too dataset #inja hala man mitonm#ggenerate compeltly new digitsz = torch.randn(    1,    latent_dim)print(z)'''tensor([[-2.4843, -1.1931,  0.8406,  0.6691,  0.8323, -1.4667, -0.0887,  0.0384,          0.9666,  0.7734, -0.4413, -0.0648,  1.2424,  1.4595, -0.3362,  0.1339,          1.4931,  0.3426, -0.6378, -1.5840, -1.1157, -0.7099, -0.0469, -1.3462,         -0.8102,  0.6867,  0.9458, -0.5482,  0.7311,  0.4828,  1.0286, -0.2729]])'''with torch.no_grad():        #az model fght decoder        #32 -->     generated = model.decoder(z)            plt.imshow(    generated.view(28,28),    cmap="gray")plt.show()